From 06bbf753476dab23eb262cb5fbab6d6d277a0ba3 Mon Sep 17 00:00:00 2001
From: Dan Carpenter <dan.carpenter@oracle.com>
Date: Fri, 4 Jan 2019 09:46:11 +0300
Subject: [PATCH] crypto: cavium/nitrox - Use after free in
 process_response_list()

We free "sr" and then dereference it on the next line.

Fixes: c9613335bf4f ("crypto: cavium/nitrox - Added AEAD cipher support")
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Signed-off-by: Herbert Xu <herbert@gondor.apana.org.au>

diff --git a/drivers/crypto/cavium/nitrox/nitrox_reqmgr.c b/drivers/crypto/cavium/nitrox/nitrox_reqmgr.c
index e34e4df8fd24..fe070d75c842 100644
--- a/drivers/crypto/cavium/nitrox/nitrox_reqmgr.c
+++ b/drivers/crypto/cavium/nitrox/nitrox_reqmgr.c
@@ -567,10 +567,10 @@ static void process_response_list(struct nitrox_cmdq *cmdq)

 		/* ORH error code */
 		err = READ_ONCE(*sr->resp.orh) & 0xff;
-		softreq_destroy(sr);

 		if (sr->callback)
 			sr->callback(sr->cb_arg, err);
+		softreq_destroy(sr);

 		req_completed++;
 	}
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug is caused by freeing the `sr` pointer with the `softreq_destroy(sr);` function before it is dereferenced to read the error code. This leads to a use-after-free condition, where the code attempts to access memory that has already been deallocated, resulting in undefined behavior.

        Commit message:
        crypto: cavium/nitrox - Use after free in
 process_response_list()

We free "sr" and then dereference it on the next line.

Fixes: c9613335bf4f ("crypto: cavium/nitrox - Added AEAD cipher support")
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Signed-off-by: Herbert Xu <herbert@gondor.apana.org.au>  

        Patch:
          */
 static void process_response_list(struct nitrox_cmdq *cmdq)
 {
 	struct nitrox_device *ndev = cmdq->ndev;
 	struct nitrox_softreq *sr;
 	int req_completed = 0, err = 0, budget;

 	/* check all pending requests */
 	budget = atomic_read(&cmdq->pending_count);

 	while (req_completed < budget) {
 		sr = get_first_response_entry(cmdq);
 		if (!sr)
 			break;

 		if (atomic_read(&sr->status) != REQ_POSTED)
 			break;

 		/* check orh and completion bytes updates */
 		if (!sr_completed(sr)) {
 			/* request not completed, check for timeout */
 			if (!cmd_timeout(sr->tstamp, ndev->timeout))
 				break;
 			dev_err_ratelimited(DEV(ndev),
 					    "Request timeout, orh 0x%016llx\n",
 					    READ_ONCE(*sr->resp.orh));
 		}
 		atomic_dec(&cmdq->pending_count);
 		atomic64_inc(&ndev->stats.completed);
 		/* sync with other cpus */
 		smp_mb__after_atomic();
 		/* remove from response list */
 		response_list_del(sr, cmdq);

 		/* ORH error code */
 		err = READ_ONCE(*sr->resp.orh) & 0xff;
-		softreq_destroy(sr);

 		if (sr->callback)
 			sr->callback(sr->cb_arg, err);
+		softreq_destroy(sr);

 		req_completed++;
 	}
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>
